#!/usr/bin/env python3
"""Validate adapter request shapes against schemas generated by installed Codex.

Generate locally with: codex app-server generate-json-schema --out <directory>
No model task or credentials are used by this checker. jsonschema is a QA-only
dependency. Full generated third-party schemas are not redistributed here.
"""
import argparse
import hashlib
import json
from pathlib import Path
import jsonschema
from agentglass.codex import sandbox

ROOT=Path(__file__).resolve().parents[1]


def main():
    p=argparse.ArgumentParser();p.add_argument('--schema-dir',type=Path,required=True);p.add_argument('--cli-version',required=True);a=p.parse_args()
    thread={'cwd':'/workspace','approvalPolicy':'never','sandbox':'read-only'}
    turn={'threadId':'schema-check-only','cwd':'/workspace','approvalPolicy':'never','input':[{'type':'text','text':'Schema check, not an executed task.'}]}
    cases=[('ThreadStartParams',thread),('ThreadResumeParams',{**thread,'threadId':'schema-check-only'}),
        ('TurnStartParams',{**turn,'sandboxPolicy':sandbox(Path('/workspace'),False)}),
        ('TurnStartParams',{**turn,'sandboxPolicy':sandbox(Path('/workspace'),True)}),
        ('TurnInterruptParams',{'threadId':'schema-check-only','turnId':'schema-check-only'})]
    checks=[]
    for name,params in cases:
        raw=(a.schema_dir/'v2'/(name+'.json')).read_bytes();jsonschema.validate(params,json.loads(raw))
        checks.append({'schema':name,'schema_sha256':hashlib.sha256(raw).hexdigest(),'parameter_keys':list(params),'passed':True})
    result={'evidence_level':2,'cli_version':a.cli_version,'model_inference_executed':False,
            'method':'Actual adapter-shaped requests validated against CLI-generated schemas; not a live task test','checks':checks}
    (ROOT/'docs/evidence/codex-schema-check.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))


if __name__=='__main__':main()
